@shaoyuyoung There are 2 reasons CPP backend generates different values:
1) Eager always uses double data type for uniform.
https://github.com/pytorch/pytorch/blob/8153340d1073c190ecf221e51abbd983286782a8/aten/src/ATen/native/Activation.cpp#L594-L602 Inductor will decompose rrelu to uniform + mul + where and use the same data type as input https://github.com/pytorch/pytorch/blob/8153340d1073c190ecf221e51abbd983286782a8/aten/src/ATen/native/cpu/DistributionTemplates.h#L272
2) rrelu generates different number of random value on eager and inductor. On eager, rrelu uses one loop to generate random value and the output value if input data <=0. On inductor, uniform will generate same number of random values as input no matter whether input data <=0 or >0, then use mul and where to calculate output.

This gap is due to the decomposition and different implementations on eager and Inductor CPP backend.

Generated code from Inductor CPP backend: 
```

cpp_fused_rrelu_with_noise_functional_0 = async_compile.cpp_pybinding(['float*', 'const float*'], '''
#include "/tmp/torchinductor_ecao/do/cdoggdcp7ux2jv5ebkajvacaprabp6b4h4m2o3zifjj6xwp2kz4n.h"
extern "C"  void kernel(float* in_out_ptr0,
                       const float* in_ptr0)
{
    {
        for(int64_t x0=static_cast<int64_t>(0L); x0<static_cast<int64_t>(10000L); x0+=static_cast<int64_t>(16L))
        {
            {
                if(C10_LIKELY(x0 >= static_cast<int64_t>(0) && x0 < static_cast<int64_t>(10000L)))
                {
                    auto tmp0 = at::vec::Vectorized<float>::loadu(in_ptr0 + static_cast<int64_t>(x0), static_cast<int64_t>(16));
                    auto tmp4 = at::vec::Vectorized<float>::loadu(in_out_ptr0 + static_cast<int64_t>(x0), static_cast<int64_t>(16));
                    auto tmp1 = static_cast<float>(0.0);
                    auto tmp2 = at::vec::Vectorized<float>(tmp1);
                    auto tmp3 = at::vec::VecMask<float,1>(tmp0 <= tmp2);
                    auto tmp5 = tmp0 * tmp4;
                    auto tmp6 = decltype(tmp5)::blendv(tmp0, tmp5, tmp3.template cast<float,1>());
                    tmp6.store(in_out_ptr0 + static_cast<int64_t>(x0));
                }
            }
        }
    }
}
''')


async_compile.wait(globals())
del async_compile

def call(args):
    arg0_1, = args
    args.clear()
    assert_size_stride(arg0_1, (1, 1, 100, 100), (10000, 10000, 100, 1))
    # Topologically Sorted Source Nodes: [x], Original ATen: [aten.rrelu_with_noise_functional]
    buf0 = torch.ops.aten.uniform.default(arg0_1, 0.125, 0.3333333333333333)
    buf1 = buf0
    assert_size_stride(buf1, (1, 1, 100, 100), (10000, 10000, 100, 1))
    # buffer buf1 is assumed to be not aligned
    del buf0
    buf2 = buf1; del buf1  # reuse
    cpp_fused_rrelu_with_noise_functional_0(buf2, arg0_1)
    del arg0_1
    return (buf2, )
```

I looked at this, and it seems that the meta kernel returns torch.empty_like(input) which copies the input dtype (float32) instead of using the dtype  parameter. This accidentally bypasses the FakeTensor is_quantized check letting quantized ops reach CPP codegen where aoti_torch_dtype_quint8 doesn't exist. 

If we fix the meta kernel to return the right dtype, it would restore the graph break. Adding the full support i.e, in fake tensors, and codegen and then actual c++ implementation is an involved fix (it seems). 

